// Soongsil University, Sangdo campus (숭실대학교 상도캠퍼스, 동작구 상도동). Data is generated by scripts/campuses/soongsil/build-package.mjs from
// the pilot (pilot/soongsil-sangdo, round 3): 25 destructible buildings (베어드홀·형남공학관 detailed, 정문 캐노피·운동장 관중석 custom,
// 21 generic; 한국기독교박물관 destructible by the user's decision), 한경직기념관 (university chapel) as protected (shield, never damaged),
// a baked ground with the pilot's ground shader (src/campuses/soongsil/ground-look.js), the sports-ground furniture and the
// non-destructible context (상도동, 서달산) fading into the haze.
// Local only until the user approves (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, SS_PLACEMENTS, SS_BUILDING_BASE, SS_HEIGHT_GRIDS, SS_HEIGHT_RANGE_M, SS_ENV_IDS, SS_ENV_MANIFEST_IDS, SS_LOOK, SS_ZONES, SS_PROVENANCE } from './data.js';
import { SS_FOOTPRINTS } from './footprints.js';
import { SS_PROTECTED } from './protected.js';
import { createSoongsilGroundLook } from './ground-look.js';

const MODEL_IDS = Object.freeze(SS_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/soongsil/${file}`, import.meta.url).href;
const HAZE = '#d6e0e5';

export const SOONGSIL = Object.freeze({
  id: 'soongsil',
  meta: Object.freeze({ school: '숭실대학교', campus: '상도캠퍼스', short: '숭실대', modelNoun: '숭실대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: SS_PLACEMENTS,
  approvedCount: SS_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['mainGate', 'hyungnam', 'baird', 'museum', 'studentUnion', 'fieldStand']),
  startBuildingId: 'mainGate',
  // Start: from the 숭실대입구역 side across the curved main-gate canopy and its wide stairs, up the slope to 형남공학관's tower and
  // the campus on the hill. World units (metres x 0.5, z = -N); azimuth = seen from the west-south-west.
  view: Object.freeze({ startFrame: Object.freeze({ min: Object.freeze([-142, -12, 2]), max: Object.freeze([-92, 10, 34]), azimuth: -1.2 }) }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: SS_ENV_MANIFEST_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: SS_HEIGHT_GRIDS, buildingBase: SS_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30, building-filled, canopy lowered by an estimate + floor-link / photo level evidence, pilot/soongsil-sangdo); not a survey' }),
  environment: Object.freeze({ provenance: SS_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the sports-ground furniture estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: SS_ENV_IDS, castShadow: Object.freeze([]), materialHook: createSoongsilGroundLook(SS_LOOK, SS_ZONES),
      fade: Object.freeze({ centre_m: Object.freeze([11.71, -4.58]), near_m: 420, far_m: 980, linear: .6, colour: HAZE }), playMargin_m: 30,
      source: 'pilot/soongsil-sangdo preview ground + landscape + context, baked' }),
  }),
  // 한경직기념관 (university chapel): never destructible; weapons meet the protective shield (src/protected-buildings.js), own small cache.
  protected: Object.freeze({
    manifestURL: asset('protected/manifest.json'),
    models: SS_PROTECTED,
  }),
  // Hazard tape around every destructible building only (src/engine/hazard-tape.js): none on the chapel or the context.
  hazardTape: Object.freeze({ footprints: SS_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 700, far: 2200 }),
    hemisphere: Object.freeze({ sky: '#eef2f4', ground: '#7d8a78', intensity: 1.3 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 2.9, position: Object.freeze([-150, 140, 100]), shadowSpan: 230 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: SS_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default SOONGSIL;
